    <span>Re-fire</span>
  </button>
  <span class="dock-sep" aria-hidden="true"></span>
  <button id="btn-toggle" type="button" aria-label="Pause" title="Play / Pause">
    <svg id="icon-pause" viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true"><rect x="6" y="4" width="4" height="16" rx="1"/><rect x="14" y="4" width="4" height="16" rx="1"/></svg>
    <svg id="icon-play" viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true" style="display:none;"><path d="M8 5v14l11-7z"/></svg>
  </button>
  <span class="dock-sep" aria-hidden="true"></span>
  <div id="speed-group" role="radiogroup" aria-label="Playback Speed">
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="0.25">0.25×</button>
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="0.5">0.5×</button>
    <button class="speed-pill is-active" type="button" role="radio" aria-checked="true" data-speed="1.0">1.0×</button>
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="2.0">2.0×</button>
  </div>
  <span class="dock-sep" aria-hidden="true"></span>
  <input id="scrubber" type="range" min="0" max="100" step="0.001" value="0" aria-label="Timeline Scrubber">
</div>
<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script id="rampart-strategy">
function createStrategy(){
  const order=[[1,'"'cannon'],[0,'bolt'],[2,'cannon'],[5,'flak'],[6,'cannon'],[3,'cannon'],[8,'cannon'],[11,'cannon'],[10,'flak'],[7,'cannon'],[4,'cannon'],[12,'cannon'],[13,'cannon'],[9,'cannon'],[15,'flak'],[14,'flak']];
  return {
    plan(s){
      const actions=[], slots=s.slots.map(p=>p.turret&&{...p.turret});
      let gold=s.gold;
      for(let step=0;step<32;step++){
        let best=-1,choice,price;
        order.forEach(([slot,type],i)=>{
          const t=slots[slot], tier=t?t.tier:0;
          if(tier===3)return;
          const cost=({cannon:90,bolt:50,flak:80}[type])*(tier===2?2:1);
          let value=(tier===0?1:tier===1?.76:.59)*Math.pow(.86,i);
          if(type==='flak' && s.wave<3)value=0;
          if(type==='bolt' && tier)value*=.38;
          if(value>best){best=value;choice={op:t?'upgrade':'build',slot,type};price=cost;}
        });
        if("'!choice||gold<price)break;
        actions.push(choice); gold-=price;
        slots[choice.slot]={type:choice.type,tier:1+(slots[choice.slot]?.tier||0)};
      }
      return actions;
    },
    target(t,c){
      let best=-1,id;
      const radius=t.type==='"'cannon'?90:t.type==='flak'?70:0;
      const dmg=({cannon:[60,96,153],bolt:[26,41,65],flak:[40,64,102]}[t.type])[t.tier-1];
      for(const e of c){
        let score=0;
        const value=v=>Math.min(v.hp,Math.max(1,dmg-v.armor))*(1+1.1/(1+v.remaining/500))*(v.type==='mender'?1.3:1)+(v.hp<=dmg-v.armor?12:0);
        if(radius){for(const v of c)if((e.x-v.x)**2+(e.y-v.y)**2<=radius*radius)score+=value(v);}
        else score=value(e)*(e.air?1.5:1);
        if(score>best){best=score;id=e.id;}
      }
      return id;
    }
  };
}
</script>
<script id=\"rampart-sim\">
function rampartSimulate(createStrategy,seed,maxTicks){
  const record=arguments[3],floor=Math.floor;
  function mulberry32(a){return function(){a=(a+0x6D2B79F5)|0;let t=Math.imul(a"'^(a>>>15),1|a);t=(t+Math.imul(t''^(t>>>7),61|t))''^t;return(t''^(t>>>14))>>>0;};}
  const draw=mulberry32(seed), strategy=createStrategy(), log=[];
  const paths=[[[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]],[[0,6],[21,6],[21,11],[23,11]]];
  const slots=[[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]].map(([x,y],slot)=>({slot,x:x*100+50,y:y*100+50,turret:null}));
  const guns=['"'bolt','cannon','frost','lance','flak'], cost=[50,90,70,120,80], damage=[26,60,10,180,40], period=[8,24,12,36,10], range=[300,260,240,360,320],splash=[0,90,0,0,70];
  const types=['grunt','runner','wisp','brute','splitter','mender','splitling'],hp=[60,40,50,150,90,70],speed=[10,20,12,6,8,8,12],bounty=[4,4,6,9,6,7,1],leak=[1,1,2,3,2,2,1],first=[1,2,3,4,6,8],weight=[10,4,3,3,2,1];
  let tick=0,wave=0,gold=250,baseHp=10,id=0,fallTick=-1,live=[],next=generate(1),events=[],queue=[],mult=[0,1000];
  function generate(w){
    const n=first.filter(x=>x<=w).length,total=weight.slice(0,n).reduce((a,b)=>a+b);
    return Array.from({length:4+floor(3*w/5)},()=>{let r=draw()%total,i=0;while(r>=weight[i])r-=weight[i++];return i;});
  }
  function locate(e){
    let p=e.progress, route=paths[e.air];
    for(let i=1;i<route.length;i++){const [x,y]=route[i-1],dx=route[i][0]-x,dy=route[i][1]-y,len=100*(Math.abs(dx)+Math.abs(dy));if(p<=len){e.x=100*x+50+Math.sign(dx)*p;e.y=100*y+50+Math.sign(dy)*p;e.dir=Math.atan2(dx,dy);break;}p-=len;}
    e.remaining=(e.air?2600:4600)-e.progress;
  }
  function spawn(t,w,p=0,childHp=0){
    const maxHp=childHp||floor(hp[t]*mult[w]/1000);
    const e={id:++id,t,type:types[t],hp:maxHp,maxHp,progress:p,w,air:+(t===2),armor:t===0?floor(w/4):t===3?6+w:0,speed:speed[t],slowed:0,age:0}; locate(e);live.push(e);
  }
  const view=({id,type,hp,maxHp,x,y,air,armor,speed,slowed,remaining})=>({id,type,hp,maxHp,x,y,air,armor,speed,slowed,remaining});
  const slotView=()=>slots.map(({slot,x,y,turret:g})=>({slot,x,y,turret:g?{type:g.type,tier:g.tier,spent:g.spent}:null}));
  function event(code,x,y,kind=0,slot=-1){if(record)events.push({code,x:x/100,z:y/100,kind,slot,tick});}
  function action(a){
    if("'!a||!Number.isInteger(a.slot)||!slots[a.slot])return;
    const s=slots[a.slot],g=s.turret,t=g?g.t:guns.indexOf(a.type);
    if(a.op==='"'build'&&"'!g&&t>=0&&gold>=cost[t]){gold-=cost[t];s.turret={type:a.type,t,tier:1,spent:cost[t],cd:0,dmg:damage[t]};log.push([tick,'"'B',s.slot,t]);}
    else if(a.op==='upgrade'&&g&&g.tier<3&&gold>=cost[t]*g.tier){const price=cost[t]*g.tier;gold-=price;g.spent+=price;g.tier++;g.dmg=floor(g.dmg*16/10);log.push([tick,'U',s.slot,g.tier]);}
    else if(a.op==='sell'&&g){gold+=floor(g.spent*7/10);s.turret=null;log.push([tick,'S',s.slot,0]);}else return;
    event(a.op,s.x,s.y,t,s.slot);
  }
  for(;tick<maxTicks;tick++){
    events=[];
    if(tick>=20&&(tick-20)%40===0){
      wave++;if(wave>1)mult[wave]=floor(mult[wave-1]*108/100);
      gold+=Math.min(50,floor(gold*5/100))+10+2*wave;
      const current=next;next=generate(wave+1);event('wave',1200,0);
      const actions=strategy.plan({tick,wave,gold,baseHp,slots:slotView(),enemies:live.map(view),nextWave:next.map(t=>types[t])});
      if(Array.isArray(actions))actions.slice(0,32).forEach(action);
      current.forEach((t,i)=>queue.push({tick:tick+i*4,w:wave,t}));queue.sort((a,b)=>a.tick-b.tick||a.w-b.w);
    }
    while(queue.length&&queue[0].tick===tick){const q=queue.shift();spawn(q.t,q.w);}
    for(let i=0;i<live.length;i++){const e=live[i];e.progress+=e.slowed?floor(e.speed*.6):e.speed;locate(e);
      if(e.remaining<=0){baseHp-=leak[e.t];log.push([tick,'L',e.id,baseHp]);event('leak',2350,1150);live.splice(i--,1);if(baseHp<=0){fallTick=tick;log.push([tick,'F',wave,0]);event('fall',2350,1150);break;}}
    }
    if(fallTick<0){
      for(const e of live){e.age++;if(e.t===5&&e.age%20===0){event('heal',e.x,e.y);for(const v of live)if((v.x-e.x)**2+(v.y-e.y)**2<=22500)v.hp=Math.min(v.maxHp,v.hp+floor(v.maxHp*8/100));}}
      for(const s of slots){
        const g=s.turret;if("'!g||(--g.cd>0))continue;g.cd=0;
        const r=range[g.t]+30*(g.tier-1),can=e=>e.air?g.t!==1&&g.t!==3:g.t!==4;
        const c=live.filter(e=>can(e)&&(e.x-s.x)**2+(e.y-s.y)**2<=r*r);if(!c.length)continue;
        const chosen=strategy.target?.({slot:s.slot,type:g.type,tier:g.tier,x:s.x,y:s.y,range:r},c.map(view));
        const e=c.find(v=>v.id===chosen)||c.reduce((a,b)=>a.remaining<=b.remaining?a:b);
        event('"'shot',e.x,e.y,g.t,s.slot);if(record)events[events.length-1].air=e.air;
        g.cd=period[g.t];const hits=splash[g.t]?live.filter(v=>can(v)&&(v.x-e.x)**2+(v.y-e.y)**2<=splash[g.t]**2):[e];
        for(const v of hits){v.hp-=Math.max(1,g.dmg-(g.t===3?0:v.armor));if(g.t===2)v.slowed=30;}
        for(let i=0;i<live.length;i++){const v=live[i];if(v.hp>0)continue;live.splice(i--,1);gold+=bounty[v.t];log.push([tick,'K',v.id,s.slot]);event('kill',v.x,v.y,v.t);if(v.t===4)for(let j=0;j<3;j++)spawn(6,v.w,v.progress,Math.max(1,floor(v.maxHp/4)));}
      }
      for(const e of live)if(e.slowed)e.slowed--;
    }
    if(record)record({wave,gold,baseHp,slots:slotView(),next:next.slice(),enemies:live.map(e=>({id:e.id,t:e.t,x:e.x/100,z:e.y/100,dir:e.dir,hp:e.hp/e.maxHp,slow:e.slowed})),events});
    if(fallTick>=0)break;
  }
  let hash=0x811c9dc5;for(const c of JSON.stringify(log))hash=Math.imul(hash"'^c.charCodeAt(0),0x01000193);
  return {score:Math.round((tick-20)/40*100)/100,fallTick,log,hash:(hash>>>0).toString(16).padStart(8,'"'0')};
}
</script>
